import sys
# Ensure project root is on sys.path before importing any project modules
sys.path.insert(0, r'/home/carme/ATPA_CIF')

# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Hyperparameters
NUM_EPOCHS = 6
BATCH_SIZE = 16
LEARNING_RATE = 0.0001
DROPOUT_RATE = 0.2
NUM_CONV_LAYERS = 3
L2_REGULARIZATION = 0.0001

# Data ingestion
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=BATCH_SIZE)

NUM_SPECIES = len(train_loader.dataset.classes)

# Model architecture
class BirdClassifier(nn.Module):
    def __init__(self, num_species, num_conv_layers=3):
        super(BirdClassifier, self).__init__()
        conv_layers = []
        in_channels = 1
        for _ in range(num_conv_layers):
            out_channels = 64 * (2 ** len(conv_layers))
            conv_layers.append(nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1))
            conv_layers.append(nn.BatchNorm2d(out_channels))
            conv_layers.append(nn.ReLU())
            in_channels = out_channels
        self.conv_layers = nn.Sequential(*conv_layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(in_channels, 128),
            nn.ReLU(),
            nn.Dropout(DROPOUT_RATE),
            nn.Linear(128, num_species)
        )
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

model = BirdClassifier(NUM_SPECIES, NUM_CONV_LAYERS).to('cuda')

# Loss and optimizer
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE, weight_decay=L2_REGULARIZATION)

# Training loop
train_subset = torch.utils.data.Subset(train_loader.dataset, range(min(15000, len(train_loader.dataset))))
train_loader = torch.utils.data.DataLoader(train_subset, batch_size=BATCH_SIZE, shuffle=True)

model.train()
for epoch in range(NUM_EPOCHS):
    total_loss = 0.0
    for inputs, labels in tqdm(train_loader, desc=f"Epoch {epoch+1}/{NUM_EPOCHS}"):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()
        
        total_loss += loss.item()
        torch.cuda.empty_cache()  # Prevent GPU fragmentation
    
    print(f"Epoch {epoch+1}, Loss: {total_loss / len(train_loader):.4f}")

# Evaluation
val_subset = torch.utils.data.Subset(train_loader.dataset, range(min(5000, len(train_loader.dataset))))
val_loader = torch.utils.data.DataLoader(val_subset, batch_size=32, shuffle=False)

model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in tqdm(val_loader, desc="Validation"):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        outputs = model(inputs)
        all_preds.extend(outputs.cpu().numpy())
        all_labels.extend(labels.cpu().numpy())

# Metrics

all_preds = np.array(all_preds)
all_labels = np.array(all_labels)

final_auc = roc_auc_score(all_labels, all_preds, average='weighted')
print(f"Final AUC: {final_auc:.4f}")

# Save metrics and model
metrics = {
    "final_train_loss": total_loss / len(train_loader),
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": NUM_EPOCHS,
    "batch_size": BATCH_SIZE,
    "training_samples": 15000,
    "eval_samples": 5000
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))

torch.save(model.state_dict(), 'model.pt')